/* eslint-disable react/no-array-index-key -- 固定槽位/列表以位置为身份 */
import type { ReactNode } from "react";

import type { ScreenSlot } from "@/components/tennantite/lib/screen-types";
import { PlayerInventory } from "@/components/tennantite/player-inventory";
import { ScreenPanel } from "@/components/tennantite/screen-panel";
import { ScreenItemSlot } from "@/components/tennantite/lib/screen-slot";
import { padSlots } from "@/components/tennantite/lib/screen-types";

export interface HopperScreenProps {
  className?: string;
  hotbarItems?: ScreenSlot[];
  items?: ScreenSlot[];
  onSlotClick?: (area: "hotbar" | "main" | "secondary", index: number) => void;
  selectedIndex?: number;
  title?: ReactNode;
}

/**
 * 漏斗界面（规格 §6）：`container/hopper.png` 176×133，5 槽 + 2 行背包。
 */
const EMPTY_HOTBAR_ITEMS: ScreenSlot[] = [];
const EMPTY_ITEMS: ScreenSlot[] = [];
export function HopperScreen({
  className,
  hotbarItems = EMPTY_HOTBAR_ITEMS,
  items = EMPTY_ITEMS,
  onSlotClick,
  selectedIndex,
  title,
}: HopperScreenProps) {
  const slots = padSlots(items, 5);
  return (
    <ScreenPanel
      background="container/hopper.png"
      className={className}
      height={133}
      title={title}
      width={176}
    >
      {slots.map((item, index) => (
        // react-doctor-disable-next-line react-doctor/no-array-index-as-key —— 位置固定槽位网格，index 即稳定身份
        <ScreenItemSlot
          item={item}
          key={index}
          label={`hopper-${index}`}
          left={43 + index * 18}
          onActivate={
            onSlotClick
              ? () => {
                  onSlotClick("secondary", index);
                }
              : undefined
          }
          top={19}
        />
      ))}
      <PlayerInventory
        bare
        hotbarItems={hotbarItems}
        hotbarY={108}
        mainRows={2}
        onSlotClick={onSlotClick}
        selectedIndex={selectedIndex}
        y={50}
      />
    </ScreenPanel>
  );
}
